package app.layan.test;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import app.layan.quran.*;import org.json.*;import java.io.*;
/** Real PDF alpha, all guide mappings and the native tab selection callback. */
public final class NightFixRegression extends Instrumentation {
 private int checks;private Bundle arguments;public void onCreate(Bundle b){super.onCreate(b);arguments=b;start();}
 private void check(boolean good,String why){checks++;if(!good)throw new AssertionError(why);}
 private View find(View v,String suffix){if(v.getClass().getName().endsWith(suffix))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View f=find(((ViewGroup)v).getChildAt(i),suffix);if(f!=null)return f;}return null;}
 private int labels(View v,int ink){int n=0;if(v instanceof TextView){check(((TextView)v).getCurrentTextColor()==ink,"Tab darkened: "+((TextView)v).getText());n++;}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)n+=labels(((ViewGroup)v).getChildAt(i),ink);return n;}
 private String text(View v){String s=v instanceof TextView?((TextView)v).getText().toString():"";if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)s+=text(((ViewGroup)v).getChildAt(i));return s;}
 private void touch(MotionEvent e){try{e.setSource(InputDevice.SOURCE_TOUCHSCREEN);check(getUiAutomation().injectInputEvent(e,true),"Touch rejected");}finally{e.recycle();}}
 private void home()throws Exception{
  Context c=getTargetContext();android.preference.PreferenceManager.getDefaultSharedPreferences(c).edit().putBoolean("nightMode",true).putBoolean("useArabicNames",true).commit();Activity a=startActivitySync(new Intent().setClassName(c,"app.layan.quran.ui.QuranActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();SystemClock.sleep(600);
  View tabs=find(a.getWindow().getDecorView(),"SlidingTabLayout"),pager=find(a.getWindow().getDecorView(),"ViewPager");check(tabs!=null&&pager!=null,"Home tabs missing");int ink=new LayanUi.Palette(a).ink;
  for(int p:new int[]{0,1,2,1,0,2,0}){final int target=p;runOnMainSync(()->{try{pager.getClass().getMethod("setCurrentItem",int.class,boolean.class).invoke(pager,target,false);tabs.getClass().getMethod("b").invoke(tabs);check(labels(tabs,ink)==3,"Three native labels");}catch(ReflectiveOperationException e){throw new RuntimeException(e);}});waitForIdleSync();}
  getUiAutomation().adoptShellPermissionIdentity("android.permission.REORDER_TASKS");try{runOnMainSync(()->a.getSystemService(ActivityManager.class).moveTaskToFront(a.getTaskId(),0));}finally{getUiAutomation().dropShellPermissionIdentity();}long focusEnd=SystemClock.elapsedRealtime()+30000;boolean focused=false;while(SystemClock.elapsedRealtime()<focusEnd){boolean[] f={false};runOnMainSync(()->f[0]=a.hasWindowFocus());if(f[0]){focused=true;break;}SystemClock.sleep(100);}check(focused,"Home never gained input focus");SystemClock.sleep(500);int[] xy=new int[2];runOnMainSync(()->pager.getLocationOnScreen(xy));int moves=0;
  for(int direction:new int[]{1,1,-1,-1,1,-1}){int before=(Integer)pager.getClass().getMethod("getCurrentItem").invoke(pager);float from=xy[0]+pager.getWidth()*(direction>0?.85f:.15f),to=xy[0]+pager.getWidth()*(direction>0?.15f:.85f),y=xy[1]+pager.getHeight()*.45f;long t=SystemClock.uptimeMillis();touch(MotionEvent.obtain(t,t,0,from,y,0));for(int i=1;i<=8;i++){SystemClock.sleep(40);touch(MotionEvent.obtain(t,SystemClock.uptimeMillis(),2,from+(to-from)*i/8f,y,0));}touch(MotionEvent.obtain(t,SystemClock.uptimeMillis(),1,to,y,0));SystemClock.sleep(700);waitForIdleSync();if(before!=(Integer)pager.getClass().getMethod("getCurrentItem").invoke(pager))moves++;runOnMainSync(()->labels(tabs,ink));}check(moves>=2,"Real swipe changes");

  JSONArray books=QiraatData.catalog(c).getJSONArray("riwayat");for(int i=0;i<books.length();i++){String id=books.getJSONObject(i).getString("id");JSONObject g=QiraatData.json(c,"guides/"+id+".json");JSONObject typography=g.optJSONObject("pageTypography");if(typography!=null&&typography.length()>0){JSONObject item=typography.getJSONObject(typography.keys().next());int page=item.getJSONArray("pages").getInt(0);runOnMainSync(()->{View panel=QiraatGuide.panel(a,id,page);check(text(panel).contains("عدد آيات"),"Heading colour guide "+id);});}}
  runOnMainSync(a::finish);waitForIdleSync();
 }
 private void save(Bitmap bitmap,String name)throws Exception{File dir=getTargetContext().getExternalFilesDir("tests");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}}
 public void onStart(){Bundle result=new Bundle();try{String scope=arguments==null?"all":arguments.getString("scope","all");if(!scope.equals("books"))home();if(scope.equals("home")){result.putString("result","PASS stable home tab colours after seven immediate selections and six real swipes; heading colour guides in all applicable riwayat");finish(Activity.RESULT_OK,result);return;}Context c=getTargetContext();android.preference.PreferenceManager.getDefaultSharedPreferences(c).edit().putBoolean("nightMode",true).putInt("nightModeTextBrightness",255).commit();JSONArray books=QiraatData.catalog(c).getJSONArray("riwayat");int edges=0;
  for(int i=0;i<books.length();i++){String id=books.getJSONObject(i).getString("id");JSONObject g=QiraatData.json(c,"guides/"+id+".json"),map=g.getJSONObject("paintMappings");QiraatInk dayInk=new QiraatInk(false,255),nightInk=new QiraatInk(true,255);java.util.Iterator<String> keys=map.keys();while(keys.hasNext()){int colour=Color.parseColor(keys.next().substring(0,7));for(int a=1;a<=255;a++){int original=Color.argb(a,Color.red(colour),Color.green(colour),Color.blue(colour));check(dayInk.pixel(original)==original,"Day shade "+id);check(Color.alpha(nightInk.pixel(original))==a,"Native coverage "+id);edges++;}check((nightInk.pixel(colour)&0xffffff)==(QiraatInk.swatch(c,colour)&0xffffff),"Night guide hue "+id);}
   JSONArray pages=g.getJSONArray("pagePaints");for(int p=0;p<604;p++)for(int k=0;k<pages.getJSONArray(p).length();k++)check(map.has(pages.getJSONArray(p).getString(k)),"Missing paint guide "+id+" "+p);
   int sample=300,max=-1;for(int p=0;p<604;p++)if(pages.getJSONArray(p).length()>max){sample=p+1;max=pages.getJSONArray(p).length();}
   try(QiraatData.Book book=new QiraatData.Book(c,id)){Bitmap day=book.render(sample,640,false,255),night=book.render(sample,640,true,255);int transparent=0,partial=0,solid=0,mismatches=0;int[] dp=new int[day.getWidth()*day.getHeight()],np=new int[dp.length];day.getPixels(dp,0,day.getWidth(),0,0,day.getWidth(),day.getHeight());night.getPixels(np,0,night.getWidth(),0,0,night.getWidth(),night.getHeight());for(int k=0;k<dp.length;k++){int alpha=dp[k]>>>24;if(alpha!=(np[k]>>>24))mismatches++;if(alpha==0)transparent++;else if(alpha<255)partial++;else solid++;}check(mismatches==0,"Rendered edge changed "+id);check(transparent>dp.length/3&&partial>100&&solid>100,"Transparent actual PDF background "+id);if(id.equals("warsh")||id.equals("ibn-wardan")||id.equals("duri-kisai")){Bitmap preview=Bitmap.createBitmap(night.getWidth(),night.getHeight(),Bitmap.Config.ARGB_8888);preview.eraseColor(0xff192b22);new Canvas(preview).drawBitmap(night,0,0,null);save(preview,"night-ink-"+id+"-"+sample);preview.recycle();}day.recycle();night.recycle();if(id.equals("ruways")){Bitmap last=book.render(604,640,false,255);int[] pixels=new int[last.getWidth()*last.getHeight()];last.getPixels(pixels,0,last.getWidth(),0,0,last.getWidth(),last.getHeight());int blue=0;for(int pixel:pixels)if(Color.alpha(pixel)>20&&Color.blue(pixel)-Color.red(pixel)>30&&Color.blue(pixel)-Color.green(pixel)>30)blue++;check(blue==0,"Ruways 604 unexpected visible blue trace");last.recycle();}}
   android.util.Log.i("LyanNightFix","PASS "+id);
  }
  result.putString("result","PASS "+checks+" assertions; "+edges+" alpha/shade samples; actual transparent PDF rendering in all twenty riwayat; 12080 guide mappings; scope="+scope);finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
}
